"""Compact social galleries and honest provider-scoped run feedback."""
CSS=r'''<style>
.galleryShellV9 .cards>p{grid-column:1/-1;line-height:1.6;margin:8px 0}.portraitSocialV6 .copy>a{white-space:nowrap;padding:6px 3px!important}
@media(min-width:1150px){.grid{grid-template-columns:230px minmax(0,1fr) 210px!important}}
#tiktokVideosV2,#instagramVideosV2,#verticalVideos{grid-template-columns:repeat(6,minmax(0,1fr))!important;gap:10px}
@media(max-width:1100px){#tiktokVideosV2,#instagramVideosV2,#verticalVideos{grid-template-columns:repeat(6,minmax(120px,1fr))!important}}
.shelfHead{margin-top:28px!important;gap:16px;align-items:center}.shelfHead>small{display:none}.shelfHead h3{font-size:14px;letter-spacing:.06em;margin:0}
.galleryShellV9{display:grid;grid-template-columns:minmax(0,1fr)40px;gap:10px;align-items:center}.galleryShellV9>.cards{min-width:0}
.galleryNextV9{height:52px;padding:0!important;font-size:24px!important;border-radius:26px!important}.galleryBarV9{display:flex;align-items:center;gap:12px;margin:10px 0 16px;font-size:12px;color:var(--muted)}
.galleryBarV9 details{margin-left:auto}.galleryBarV9 summary{cursor:pointer}.galleryKeywordsV9{display:grid;gap:10px;padding:12px;border:1px solid var(--line);border-radius:10px;background:var(--p2)}.galleryKeywordsV9 label{display:grid;gap:4px}.galleryKeywordsV9 input{width:100%;min-width:200px;background:#101923;color:var(--ink);border:1px solid var(--line);border-radius:6px;padding:8px}
.providerProgressV9{display:flex;align-items:center;gap:10px;min-height:28px;margin:8px 0;color:var(--muted);font-size:12px}.providerProgressV9 progress{width:110px;height:5px;accent-color:#bbdf65}.providerProgressV9[data-state=failed]{color:#ffadad}.providerProgressV9[data-state=attention]{color:#ffe4a0;background:#493c28;border:1px solid #b48b41;padding:14px;border-radius:12px;flex-wrap:wrap}.providerProgressV9[data-state=attention] button{margin-left:auto}
.portraitSocialV6{border-radius:12px!important;overflow:hidden;background:#111a24!important}.portraitSocialV6>.copy{display:flex;flex-direction:column;gap:8px;padding:12px!important}.portraitSocialV6 .copy>b{font-size:12px;line-height:1.45}.portraitSocialV6 .copy>div,.portraitSocialV6 .socialStateV2{display:none}.portraitSocialV6 .copy>details{font-size:11px;color:var(--muted)}
.portraitSocialV6 .copy>a,.portraitSocialV6 .copy>button{box-sizing:border-box;display:flex!important;align-items:center;justify-content:center;min-height:32px;margin:0!important;padding:6px 8px;border-radius:7px;border:1px solid #344657;background:#1b2937;color:#e9f0f5;text-decoration:none;font-size:11px;font-weight:600;letter-spacing:0}.portraitSocialV6 .copy>a:hover{background:#2b4052;border-color:#718da6}.portraitSocialV6 .copy>.select:disabled{display:none!important}.socialMediaStatusV8{font-size:10px;line-height:1.45}
#gifLightboxV9{border:1px solid #364653;border-radius:14px;padding:16px;background:#111922;color:#e9f0f5;max-width:85vw;max-height:88vh;text-align:center}#gifLightboxV9::backdrop{background:#000b;backdrop-filter:blur(4px)}#gifLightboxV9 img{display:block;height:min(72vh,640px);width:auto;max-width:75vw;object-fit:contain;border-radius:8px}#gifLightboxV9 [hidden]{display:none}#gifLightboxV9 p{font-size:12px;max-width:340px}#closeLightbox{display:none}
</style>'''

JS=r'''
const galleryV9=new Map(),searchesV9=new Map(),galleryProvidersV26=['youtube','youtube_shorts','pexels','envato','web_video','tiktok','instagram','images'];let gifRequestV9=0;
$('lightbox').addEventListener('click',e=>{const b=$('lightbox').getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom){$('lightboxVideo').pause();$('lightbox').close()}});
const stageBaseV9=startStage;startStage=async(path)=>{if(path==='source/videos')beginSearchV9(['youtube_shorts'],'*');try{return await stageBaseV9(path)}catch(e){finishSearchV9({status:'FAILED'});throw e}};
function galleryKeyV9(provider,beat=state.active){return `${state.pid}:${beat}:${provider}`}
function galleryStateV9(provider){const key=galleryKeyV9(provider);if(!galleryV9.has(key))galleryV9.set(key,{page:0,round:Math.max(0,Number(localStorage.getItem('round:'+key)||0)),ids:[],overrides:{}});return galleryV9.get(key)}
function orderedSocialV9(chunk,provider){const g=galleryStateV9(provider),rows=provider==='images'?chunk.assets.filter(a=>a.kind==='image'):chunk.assets.filter(a=>a.provider===provider&&a.kind==='video'),index=new Map(rows.map(a=>[a.asset_id,a]));g.ids=g.ids.filter(id=>index.has(id));for(const a of rows)if(!g.ids.includes(a.asset_id))g.ids.push(a.asset_id);return g.ids.map(id=>index.get(id))}
function beginSearchV9(providers,beat,options={}){for(const provider of providers)searchesV9.set(galleryKeyV9(provider,beat),{busy:true,text:'Avvio ricerca…',state:'busy',retryOptions:{...options}});renderSearchStatusV9()}
async function showChallengeWindowV11(provider,s,button){button.disabled=true;s.windowMessage='Apertura della finestra…';try{await api(`/social/${provider}/login`,{method:'POST'});s.windowMessage='Finestra richiamata. Se resta dietro RAMBLA, selezionala dalla barra delle applicazioni. Risolvi il CAPTCHA, poi premi Rilancia ricerca.'}catch(e){s.windowMessage='Impossibile mostrare la finestra: '+(e.message||String(e))}finally{renderSearchStatusV9()}}
async function retrySocialV11(provider,s){if(state.run)return;const chunk=activeChunkV2();if(!chunk||chunk.action!=='BROLL')return;const options={...(s.retryOptions||{})};const g=galleryStateV9(provider);if(options.variation_round>0)g.pending={before:orderedSocialV9(chunk,provider).length,round:options.variation_round};await researchBeatV2('append',[provider],options)}
function renderSearchStatusV9(){for(const provider of galleryProvidersV26){const box=document.getElementById('progressV9-'+provider);if(!box)continue;const s=searchesV9.get(galleryKeyV9(provider))||searchesV9.get(galleryKeyV9(provider,'*'));box.dataset.state=s?.state||'idle';box.innerHTML=s?.busy?'<progress aria-label="Ricerca in corso"></progress><span></span>':'<span></span>';box.querySelector('span').textContent=s?.text||'Pronto';if(s?.attention){box.setAttribute('role','alert');box.querySelector('progress')?.remove();const button=document.createElement('button');button.textContent='Mostra finestra '+provider;button.onclick=()=>showChallengeWindowV11(provider,s,button);box.appendChild(button);const retry=document.createElement('button');retry.textContent='Rilancia ricerca';retry.disabled=!!state.run;retry.title=state.run?'Attendi la fine della ricerca in corso':'Dopo aver risolto il CAPTCHA, riprova su questa frase';retry.onclick=()=>retrySocialV11(provider,s);box.appendChild(retry);if(s.windowMessage){const note=document.createElement('span');note.setAttribute('role','status');note.textContent=s.windowMessage;box.appendChild(note)}}else box.setAttribute('role','status');}}
window.ramblaRunProgress=(r)=>{for(const [key,s] of searchesV9){if(!s.busy)continue;const provider=key.split(':').pop(),e=(r.events||[]).filter(e=>e.data?.provider===provider||(e.data?.providers||[]).includes(provider)).at(-1);const issue=(r.events||[]).filter(e=>e.stage==='provider_attention'&&e.data?.provider===provider).at(-1);if(issue){s.attention=issue.data.reason;s.state='attention';s.text=s.attention==='challenge_required'?'CAPTCHA richiesto: risolvilo nella finestra aperta, poi rilancia la ricerca.':s.attention==='login_required'?'Login richiesto: accedi nella finestra aperta, poi rilancia la ricerca.':'Errore del provider: consulta la diagnostica prima di riprovare.'}else if(!s.attention)s.text=e?.message||r.last_message||'Ricerca in corso…'}renderSearchStatusV9()};
function finishSearchV9(r){for(const [key,s] of searchesV9){if(!s.busy)continue;s.busy=false;if(s.attention){s.state='attention';const g=galleryV9.get(key);if(g)delete g.pending;continue}s.state=r.status==='SUCCEEDED'?'done':'failed';const provider=key.split(':').pop(),g=galleryV9.get(key);s.text=r.status==='SUCCEEDED'?'Ricerca completata':r.status==='CANCELLED'?'Ricerca annullata':'Ricerca non riuscita · apri diagnostica';if(g?.pending){if(r.status==='SUCCEEDED'){g.round=g.pending.round;localStorage.setItem('round:'+key,String(g.round));if(key===galleryKeyV9(provider)){const count=orderedSocialV9(activeChunkV2(),provider).length;g.page=count>g.pending.before?Math.floor(g.pending.before/6):g.page;s.text=count>g.pending.before?`${count-g.pending.before} nuove alternative uniche aggiunte`:'Nessun risultato nuovo aggiunto · controlla diagnostica'}}delete g.pending}}renderSearchStatusV9()}
async function showSocialGifV9(a){let dialog=$('gifLightboxV9');if(!dialog){dialog=document.createElement('dialog');dialog.id='gifLightboxV9';dialog.setAttribute('aria-label','Anteprima animata');dialog.innerHTML='<p role="status"></p><img hidden alt="Momenti distribuiti nel video">';document.body.appendChild(dialog);dialog.onclick=e=>{const b=dialog.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)dialog.close()};dialog.addEventListener('close',()=>{gifRequestV9++;dialog.querySelector('img').removeAttribute('src')})}const request=++gifRequestV9,img=dialog.querySelector('img'),label=dialog.querySelector('p');img.hidden=true;label.textContent='Preparazione GIF · sei momenti del video…';dialog.showModal();try{const r=await api(`/projects/${state.pid}/social-media/${encodeURIComponent(a.asset_id)}/hover`,{method:'POST'});if(request!==gifRequestV9||!dialog.open)return;img.src=r.url;img.hidden=false;label.textContent='Anteprima animata · clicca fuori per chiudere'}catch(e){if(request===gifRequestV9)label.textContent=e.message||'Anteprima non disponibile'}}
function galleryNavigationV10(g,count,busy){return {previous:g.page>0,next:(g.page+1)*6<count,search:!busy,pages:Math.max(1,Math.ceil(count/6))}}
function providerHeaderV25(shell){let node=shell.previousElementSibling;while(node&&!node.classList.contains('shelfHead'))node=node.previousElementSibling;if(node)node.classList.add('providerHeaderV25');return node}
function installGalleryV9(chunk,id,provider){
 const box=$(id);if(!box)return;
 const g=galleryStateV9(provider),rows=orderedSocialV9(chunk,provider);
 g.round=Math.max(g.round,Number(chunk.research_round||0));localStorage.setItem('round:'+galleryKeyV9(provider),String(g.round));
 g.page=Math.min(g.page,Math.max(0,Math.ceil(rows.length/6)-1));
 const nav=galleryNavigationV10(g,rows.length,!!state.run);
 box.innerHTML=rows.slice(g.page*6,g.page*6+6).map(card).join('')||`<p class="muted">${esc(socialEmptyMessageV2(chunk,provider))}</p>`;
 document.getElementById('moreV2-'+id)?.remove();
 let shell=box.parentElement;
 if(!shell.classList.contains('galleryShellV9')){shell=document.createElement('div');shell.className='galleryShellV9';box.before(shell);shell.appendChild(box)}
 const redraw=()=>{installGalleryV9(chunk,id,provider);bindCardsV2(chunk);decorateSocialCardsV2(chunk)};
 for(const [direction,label,enabled] of [['previous','Risultati precedenti',nav.previous],['next','Risultati successivi',nav.next]]){
  let button=shell.querySelector('.galleryNavV10-'+direction);
  if(!button){button=document.createElement('button');button.className='galleryNavV10 galleryNavV10-'+direction;button.type='button';button.innerHTML=`<svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="${direction==='previous'?'M15 5l-7 7 7 7':'M9 5l7 7-7 7'}" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>`;direction==='previous'?shell.prepend(button):shell.appendChild(button)}
  button.disabled=!enabled;button.title=label;button.setAttribute('aria-label',label);
  button.onclick=()=>{const current=galleryNavigationV10(g,rows.length,!!state.run);if(!current[direction])return;g.page+=direction==='previous'?-1:1;redraw()};
 }
 shell.querySelector('.galleryNextV9')?.remove();
 let progress=$('progressV9-'+provider);if(!progress){progress=document.createElement('div');progress.id='progressV9-'+provider;progress.className='providerProgressV9';progress.setAttribute('role','status');shell.before(progress)}
 let bar=$('galleryBarV9-'+provider);if(!bar){bar=document.createElement('div');bar.id='galleryBarV9-'+provider}
 bar.className='galleryBarV9 providerControlsV25';const header=providerHeaderV25(shell);if(header)header.appendChild(bar);else shell.after(bar);
 const keywordOpen=bar.querySelector('details')?.open||false;
 bar.innerHTML=`<span class="galleryPageV10">Pagina ${g.page+1} / ${nav.pages}<small>${rows.length?g.page*6+1:0}–${Math.min(rows.length,(g.page+1)*6)} di ${rows.length} risultati</small></span><button class="gallerySearchV10" ${nav.search?'':'disabled'}>${state.run?'Ricerca in corso…':'＋ Cerca fino a 6 nuove'}</button><span class="galleryRoundV10">${g.round} ricerche aggiuntive</span><details ${keywordOpen?'open':''}><summary>Keyword per shot</summary><div class="galleryKeywordsV9"></div></details>`;
 bar.querySelector('.gallerySearchV10').onclick=async()=>{if(!galleryNavigationV10(g,rows.length,!!state.run).search)return;g.pending={before:rows.length,round:g.round+1};try{await researchBeatV2('append',[provider],{variation_round:g.round+1,query_overrides:g.overrides})}catch(e){delete g.pending;searchesV9.set(galleryKeyV9(provider),{busy:false,state:'failed',text:e.message});renderSearchStatusV9()}};
 const fields=bar.querySelector('.galleryKeywordsV9');
 for(const shot of chunk.visual_plan?.shots||[]){const label=document.createElement('label');label.textContent=shot.shot_id;const input=document.createElement('input');input.maxLength=180;input.placeholder=(shot.video_queries||[])[0]||'Keyword concrete';input.value=g.overrides[shot.shot_id]||'';input.oninput=()=>{g.overrides[shot.shot_id]=input.value.trim()};label.appendChild(input);fields.appendChild(label)}
 renderSearchStatusV9();
}
'''
